import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { getBoard, updateBoard, deleteBoard } from '../services/api';
import { getColumns, createColumn, updateColumn, deleteColumn } from '../services/api';
import Column from './Column';

const Board = () => {
  const { boardId } = useParams();
  const [board, setBoard] = useState(null);
  const [columns, setColumns] = useState([]);
  const [newColumnTitle, setNewColumnTitle] = useState('');
  const [isEditing, setIsEditing] = useState(false);
  const [editTitle, setEditTitle] = useState('');
  const [editDescription, setEditDescription] = useState('');

  useEffect(() => {
    fetchBoard();
    fetchColumns();
  }, [boardId]);

  const fetchBoard = async () => {
    const data = await getBoard(boardId);
    setBoard(data);
    setEditTitle(data.title);
    setEditDescription(data.description);
  };

  const fetchColumns = async () => {
    const data = await getColumns(boardId);
    setColumns(data);
  };

  const handleCreateColumn = async (e) => {
    e.preventDefault();
    if (!newColumnTitle.trim()) return;

    await createColumn(newColumnTitle, boardId, columns.length);
    setNewColumnTitle('');
    fetchColumns();
  };

  const handleUpdateBoard = async (e) => {
    e.preventDefault();
    await updateBoard(boardId, editTitle, editDescription, board.order);
    setIsEditing(false);
    fetchBoard();
  };

  const handleDeleteBoard = async () => {
    if (window.confirm('Are you sure you want to delete this board?')) {
      await deleteBoard(boardId);
      window.location.href = '/';
    }
  };

  const handleDragStart = (e, columnId) => {
    e.dataTransfer.setData('columnId', columnId);
  };

  const handleDragOver = (e) => {
    e.preventDefault();
  };

  const handleDrop = async (e, targetColumnId) => {
    e.preventDefault();
    const draggedColumnId = e.dataTransfer.getData('columnId');

    if (draggedColumnId === targetColumnId) return;

    const draggedColumn = columns.find(c => c._id === draggedColumnId);
    const targetColumn = columns.find(c => c._id === targetColumnId);

    if (!draggedColumn || !targetColumn) return;

    const newOrder = targetColumn.order;
    await updateColumn(draggedColumnId, draggedColumn.title, newOrder);
    fetchColumns();
  };

  if (!board) return <div>Loading...</div>;

  return (
    <div className="board">
      <div className="board-header">
        {isEditing ? (
          <form onSubmit={handleUpdateBoard}>
            <input
              type="text"
              value={editTitle}
              onChange={(e) => setEditTitle(e.target.value)}
            />
            <input
              type="text"
              value={editDescription}
              onChange={(e) => setEditDescription(e.target.value)}
            />
            <button type="submit">Save</button>
            <button type="button" onClick={() => setIsEditing(false)}>Cancel</button>
          </form>
        ) : (
          <>
            <h2>{board.title}</h2>
            <p>{board.description}</p>
            <button onClick={() => setIsEditing(true)}>Edit</button>
            <button onClick={handleDeleteBoard}>Delete</button>
          </>
        )}
      </div>

      <form onSubmit={handleCreateColumn}>
        <input
          type="text"
          value={newColumnTitle}
          onChange={(e) => setNewColumnTitle(e.target.value)}
          placeholder="New column title"
        />
        <button type="submit">Create Column</button>
      </form>

      <div className="columns">
        {columns.map((column) => (
          <div
            key={column._id}
            className="column-container"
            draggable
            onDragStart={(e) => handleDragStart(e, column._id)}
            onDragOver={handleDragOver}
            onDrop={(e) => handleDrop(e, column._id)}
          >
            <Column
              column={column}
              onUpdate={fetchColumns}
              onDelete={fetchColumns}
            />
          </div>
        ))}
      </div>
    </div>
  );
};

export default Board;
